Below is a **pytest‑compatible test suite** for the `zip_dicts` function.  
It covers:

* **Happy‑path** – normal dictionaries with overlapping and unique keys.  
* **Edge cases** – empty dictionaries, a single dictionary, many dictionaries, mixed key/value types, `None` values, and keys that are different hashable objects (`int`, `tuple`, `str`).  
* **Error cases** – calling with no arguments, passing a non‑`dict` argument, and dictionaries that contain an unhashable key (e.g. a list).

```python
# test_zip_dicts.py

import pytest
from typing import Any, Dict, List

# The function under test – adjust the import path as needed.
from your_module import zip_dicts   # <-- change this to the actual import


# ----------------------------------------------------------------------
# Helper
# ----------------------------------------------------------------------
def list_of_values_for_key(result: Dict[Any, List[Any]], key: Any) -> List[Any]:
    """Return the list stored under `key` in `result`."""
    assert key in result, f"Key {key!r} not found in result"
    return result[key]


# ----------------------------------------------------------------------
# Happy‑path tests
# ----------------------------------------------------------------------
class TestZipDictsHappyPath:
    """Typical usage scenarios that should work correctly."""

    def test_two_simple_dicts(self):
        d1 = {"a": 1, "b": 2}
        d2 = {"b": 3, "c": 4}
        result = zip_dicts(d1, d2)

        # Every key appears exactly once.
        assert set(result.keys()) == {"a", "b", "c"}

        # The list length equals the number of input dicts (2).
        for v in result.values():
            assert len(v) == 2

        # Check each key.
        assert list_of_values_for_key(result, "a") == [1, None]
        assert list_of_values_for_key(result, "b") == [2, 3]
        assert list_of_values_for_key(result, "c") == [None, 4]

    def test_multiple_dicts(self):
        d1 = {"x": 10}
        d2 = {"y": 20}
        d3 = {"z": 30}
        result = zip_dicts(d1, d2, d3)

        assert set(result.keys()) == {"x", "y", "z"}
        for v in result.values():
            assert len(v) == 3

        assert list_of_values_for_key(result, "x") == [10, None, None]
        assert list_of_values_for_key(result, "y") == [None, 20, None]
        assert list_of_values_for_key(result, "z") == [None, None, 30]

    def test_single_dict(self):
        d = {"foo": "bar", "baz": 42}
        result = zip_dicts(d)

        assert result == {"foo": ["bar"], "baz": [42]}
        # Each value list must have length 1 (only one input dict).
        for v in result.values():
            assert len(v) == 1

    def test_all_empty_dicts(self):
        result = zip_dicts({}, {}, {})
        assert result == {}

    def test_mixed_value_types(self):
        d1 = {"a": None, "b": [1, 2], "c": {"nested": "dict"}}
        d2 = {"a": 0, "b": "string", "d": (3,)}
        result = zip_dicts(d1, d2)

        assert set(result.keys()) == {"a", "b", "c", "d"}
        assert list_of_values_for_key(result, "a") == [None, 0]
        assert list_of_values_for_key(result, "b") == [[1, 2], "string"]
        assert list_of_values_for_key(result, "c") == [{"nested": "dict"}, None]
        assert list_of_values_for_key(result, "d") == [None, (3,)]

    def test_non_string_keys(self):
        d1 = {1: "one", (2, 3): "tuple"}
        d2 = {1: "ONE", "two": 2}
        result = zip_dicts(d1, d2)

        assert set(result.keys()) == {1, (2, 3), "two"}
        assert list_of_values_for_key(result, 1) == ["one", "ONE"]
        assert list_of_values_for_key(result, (2, 3)) == ["tuple", None]
        assert list_of_values_for_key(result, "two") == [None, 2]

    def test_result_is_a_dict(self):
        d1 = {"k": 1}
        d2 = {"k": 2}
        result = zip_dicts(d1, d2)
        assert isinstance(result, dict)

    def test_input_dicts_not_modified(self):
        d1 = {"a": 1}
        d2 = {"b": 2}
        original_d1 = dict(d1)
        original_d2 = dict(d2)

        zip_dicts(d1, d2)

        assert d1 == original_d1
        assert d2 == original_d2


# ----------------------------------------------------------------------
# Edge‑case tests
# ----------------------------------------------------------------------
class TestZipDictsEdgeCases:
    """Situations that are legal but “on the edge” of typical usage."""

    def test_many_dicts(self):
        # 5 dicts, each containing a single unique key.
        dicts = [{"k0": 0}, {"k1": 1}, {"k2": 2}, {"k3": 3}, {"k4": 4}]
        result = zip_dicts(*dicts)

        assert set(result.keys()) == {"k0", "k1", "k2", "k3", "k4"}
        for i, v in enumerate(result.values()):
            assert len(v) == 5
            # Only the dict that owns the key has a non‑None value.
            assert v.count(None) == 4

    def test_all_keys_present_in_every_dict(self):
        d1 = {"x": 1, "y": 2}
        d2 = {"x": 3, "y": 4}
        d3 = {"x": 5, "y": 6}
        result = zip_dicts(d1, d2, d3)

        assert set(result.keys()) == {"x", "y"}
        assert list_of_values_for_key(result, "x") == [1, 3, 5]
        assert list_of_values_for_key(result, "y") == [2, 4, 6]

    def test_empty_dicts_mixed_with_non_empty(self):
        d1 = {}
        d2 = {"a": 10}
        d3 = {}
        result = zip_dicts(d1, d2, d3)

        assert set(result.keys()) == {"a"}
        assert list_of_values_for_key(result, "a") == [None, 10, None]

    def test_none_values_are_preserved(self):
        d1 = {"k": None}
        d2 = {"k": "value"}
        result = zip_dicts(d1, d2)

        assert list_of_values_for_key(result, "k") == [None, "value"]


# ----------------------------------------------------------------------
# Error‑case tests
# ----------------------------------------------------------------------
class TestZipDictsErrors:
    """Inputs that should cause the function to raise an exception."""

    def test_no_arguments(self):
        """Calling zip_dicts() without any dict raises TypeError."""
        with pytest.raises(TypeError, match="union.*at least 1 argument"):
            zip_dicts()

    def test_non_dict_argument_list(self):
        """Passing a list where a dict is expected raises AttributeError."""
        with pytest.raises(AttributeError, match="'list' object has no attribute 'get'"):
            zip_dicts({"a": 1}, [1, 2])

    def test_non_dict_argument_string(self):
        """Passing a string (iterable, but not a mapping) raises AttributeError."""
        with pytest.raises(AttributeError, match="'str' object has no attribute 'get'"):
            zip_dicts({"a": 1}, "ab")

    def test_non_dict_argument_int(self):
        """Passing an int raises AttributeError when .get is called."""
        with pytest.raises(AttributeError, match="'int' object has no attribute 'get'"):
            zip_dicts({"a": 1}, 42)

    def test_dict_with_unhashable_key(self):
        """A dict that uses a list as a key makes the union fail with TypeError."""
        d1 = {"valid": 1, (1, 2): "tuple"}
        d2 = {"valid": 2, [3, 4]: "list"}  # <-- unhashable key
        with pytest.raises(TypeError, match="unhashable type"):
            zip_dicts(d1, d2)

    def test_mixed_hashable_and_unhashable_keys(self):
        """Even if only one dict contains an unhashable key, the call fails."""
        d1 = {"a": 1}
        d2 = {"b": [1, 2]}  # list as a value, not a key – still fine
        # This should NOT raise – values are unrestricted.
        result = zip_dicts(d1, d2)
        assert result == {"a": [1, None], "b": [None, [1, 2]]}

        # Now make the unhashable a key.
        d3 = {[5, 6]: "list key"}
        with pytest.raises(TypeError, match="unhashable type"):
            zip_dicts(d1, d3)

    def test_non_iterable_in_union(self):
        """If an object in *dicts is not iterable at all, union fails."""
        class NonIterable:
            pass

        with pytest.raises(TypeError):
            zip_dicts({"a": 1}, NonIterable())


# ----------------------------------------------------------------------
# Optional: run the tests directly
# ----------------------------------------------------------------------
if __name__ == "__main__":
    pytest.main([__file__, "-v"])
```

### How to use
1. Place the file **in the same directory** as the module that contains `zip_dicts` (or adjust the import line at the top).  
2. Run the tests with:

```bash
pytest test_zip_dicts.py -v
```

All tests should pass when the implementation matches the docstring‑style code you posted. If you intentionally modify `zip_dicts` (e.g., to handle the empty‑argument case gracefully), just update the corresponding test expectations accordingly.
